// Generated by Coalesce SDLC Engine for CUSTOM-Q9GE

const attemptHistory: number[] = [];
const MAX_ATTEMPTS = 5;
const WINDOW_MS = 60 * 1000;

export function checkRateLimit(): { allowed: boolean; remaining: number } {
  const now = Date.now();
  while (attemptHistory.length && now - attemptHistory[0] > WINDOW_MS) {
    attemptHistory.shift();
  }
  if (attemptHistory.length >= MAX_ATTEMPTS) {
    return { allowed: false, remaining: 0 };
  }
  attemptHistory.push(now);
  return { allowed: true, remaining: MAX_ATTEMPTS - attemptHistory.length };
}
